window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-406e2f09c10f7e14"]={"versions": [{"id": "FIG-406e2f09c10f7e14", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Empfangs-Indikations-Handlings (Rx Indication Handling und Signal Unpacking) im AUTOSAR Classic Platform Kommunikations-Stack (AUTOSAR_SWS_COM). Das Diagramm stellt das Zusammenwirken zwischen dem PDU Router (PduR), dem AUTOSAR COM-Modul (Com) und der Runtime Environment (Rte) dar und visualisiert die architektonische Gegenüberstellung der beiden Signal-Entpackungsstrategien „Immediate“ (synchron im Aufrufkontext) und „Deferred“ (asynchron/gepuffert im Taskkontext).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Komponenten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li>«module» PduR: Untere Schnittstellenschicht im Kommunikationsstack, leitet empfangene I-PDUs an das COM-Modul weiter.\n</li><li>«module» Com: Zentrales Kommunikationsmodul (mit Prozess-/Task-Symbol), zuständig für Signalextraktion, Pufferung und Routing.\n</li><li>«module» Rte: AUTOSAR Runtime Environment zur Signalweiterleitung an Software-Komponenten (SWCs).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Com_RxIndication(PduIdType, PduInfoType*): Synchrone Empfangsschnittstelle von Com, parametrisiert mit PDU-Identifikator und Zeiger auf PDU-Nutzdaten/Längeninformation.\n</li><li>Rte_COMCbk_signalX() / Rte_COMCbk_signalY(): Konfigurierbare COM-Callback-Funktionen zur Benachrichtigung der RTE über aktualisierte Signale (signalX, signalY).\n</li><li>internal processing(): Interne Verarbeitungsschritte innerhalb der RTE.\n</li><li>set flag, copy data(): Interne Operation von Com zur Datenpufferung und Flag-Setzung für den asynchronen Verarbeitungsmodus.\n</li><li>check flag(): Periodische interne Prüfung des Puffer-Flags durch Com (typischerweise innerhalb Com_MainFunctionRx()).\n</li></ul>\n<p class=\"fig-p\">Interaktionsrahmen (Combined Fragments):</p>\n<ul class=\"fig-list\"><li>alt Unpacking mit Operanden [Unpack.Immediate] und [Unpack.Deferred].\n</li><li>alt check flag (geschachtelt in Deferred) mit Operanden [flag set] und [flag not set].\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf teilt sich über das Combined Fragment „alt Unpacking“ in zwei alternative Pfade auf:</p>\n<ol class=\"fig-list\"><li>Modus [Unpack.Immediate]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt das Signal-Unpacking unmittelbar im Ausführungskontext der Indikation aus.\n</li><li>Com benachrichtigt nacheinander die RTE über synchrone Callback-Aufrufe Rte_COMCbk_signalX() und Rte_COMCbk_signalY().\n</li><li>Jede Callback-Ausführung stößt in der RTE ein internal processing() an und kehrt zu Com zurück.\n</li><li>Nach Abschluss der Benachrichtigungen kehrt der Kontrollfluss von Com_RxIndication an PduR zurück.\n</li></ul>\n<ol class=\"fig-list\"><li>Modus [Unpack.Deferred]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt die interne Operation set flag, copy data() aus (Kopieren der empfangenen Daten in den I-PDU-Puffer, Setzen des Verarbeitungs-Flags) und kehrt sofort synchron zu PduR zurück.\n</li><li>Zu einem späteren Zeitpunkt führt Com im eigenen Kontext check flag() aus.\n</li><li>Fragment „alt check flag“:\n<ul class=\"fig-list\"><li>Zweig [flag set]: Com ruft sequenziell Rte_COMCbk_signalX() und Rte_COMCbk_signalY() auf; die RTE verarbeitet die Daten jeweils intern (internal processing()) und kehrt zurück.\n</li><li>Zweig [flag not set]: Es erfolgen keine weiteren Signal-Callbacks an die RTE.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ spiegelt das Diagramm die Realisierung des Konfigurationsparameters ComIPduSignalProcessing wider:</p>\n<ul class=\"fig-list\"><li>IMMEDIATE: Minimale Signallatenz, da Signalextraktion und RTE-Benachrichtigung direkt in Com_RxIndication ablaufen. Da Com_RxIndication typischerweise im ISR- oder Bus-Treiber-Kontext aufgerufen wird, müssen Callback-Funktionen (Rte_COMCbk_&lt;signal&gt;) extrem schlank und nicht-blockierend ausgelegt sein, um die Interrupt-Latenzen nicht zu verletzen.\n</li><li>DEFERRED: Entkopplung von hardwarenahem Empfang und Signalverarbeitung. Der ISR-Kontext wird auf das Kopieren der PDU-Payload in den internen COM-Puffer beschränkt. Das Entpacken und Auslösen der RTE-Callbacks erfolgt deterministisch im Rahmen des zyklischen Com_MainFunctionRx()-Tasks.\n</li><li>Für Entwickler relevant: Signal-Callbacks (signalX, signalY) werden in beiden Modi in identischer Signatur und Reihenfolge ausgelöst; das Diagramm verdeutlicht jedoch die signifikanten Unterschiede bezüglich Task-Kontext, Pufferbedarf und Ausführungszeitpunkt.\n</li></ul>"}, {"id": "FIG-9670781b449504d6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Empfangs-Indikations-Handlings (Rx Indication Handling und Signal Unpacking) im AUTOSAR Classic Platform Kommunikations-Stack (AUTOSAR_SWS_COM). Das Diagramm stellt das Zusammenwirken zwischen dem PDU Router (PduR), dem AUTOSAR COM-Modul (Com) und der Runtime Environment (Rte) dar und visualisiert die architektonische Gegenüberstellung der beiden Signal-Entpackungsstrategien „Immediate“ (synchron im Aufrufkontext) und „Deferred“ (asynchron/gepuffert im Taskkontext).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Komponenten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li>«module» PduR: Untere Schnittstellenschicht im Kommunikationsstack, leitet empfangene I-PDUs an das COM-Modul weiter.\n</li><li>«module» Com: Zentrales Kommunikationsmodul (mit Prozess-/Task-Symbol), zuständig für Signalextraktion, Pufferung und Routing.\n</li><li>«module» Rte: AUTOSAR Runtime Environment zur Signalweiterleitung an Software-Komponenten (SWCs).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Com_RxIndication(PduIdType, PduInfoType*): Synchrone Empfangsschnittstelle von Com, parametrisiert mit PDU-Identifikator und Zeiger auf PDU-Nutzdaten/Längeninformation.\n</li><li>Rte_COMCbk_signalX() / Rte_COMCbk_signalY(): Konfigurierbare COM-Callback-Funktionen zur Benachrichtigung der RTE über aktualisierte Signale (signalX, signalY).\n</li><li>internal processing(): Interne Verarbeitungsschritte innerhalb der RTE.\n</li><li>set flag, copy data(): Interne Operation von Com zur Datenpufferung und Flag-Setzung für den asynchronen Verarbeitungsmodus.\n</li><li>check flag(): Periodische interne Prüfung des Puffer-Flags durch Com (typischerweise innerhalb Com_MainFunctionRx()).\n</li></ul>\n<p class=\"fig-p\">Interaktionsrahmen (Combined Fragments):</p>\n<ul class=\"fig-list\"><li>alt Unpacking mit Operanden [Unpack.Immediate] und [Unpack.Deferred].\n</li><li>alt check flag (geschachtelt in Deferred) mit Operanden [flag set] und [flag not set].\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf teilt sich über das Combined Fragment „alt Unpacking“ in zwei alternative Pfade auf:</p>\n<ol class=\"fig-list\"><li>Modus [Unpack.Immediate]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt das Signal-Unpacking unmittelbar im Ausführungskontext der Indikation aus.\n</li><li>Com benachrichtigt nacheinander die RTE über synchrone Callback-Aufrufe Rte_COMCbk_signalX() und Rte_COMCbk_signalY().\n</li><li>Jede Callback-Ausführung stößt in der RTE ein internal processing() an und kehrt zu Com zurück.\n</li><li>Nach Abschluss der Benachrichtigungen kehrt der Kontrollfluss von Com_RxIndication an PduR zurück.\n</li></ul>\n<ol class=\"fig-list\"><li>Modus [Unpack.Deferred]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt die interne Operation set flag, copy data() aus (Kopieren der empfangenen Daten in den I-PDU-Puffer, Setzen des Verarbeitungs-Flags) und kehrt sofort synchron zu PduR zurück.\n</li><li>Zu einem späteren Zeitpunkt führt Com im eigenen Kontext check flag() aus.\n</li><li>Fragment „alt check flag“:\n<ul class=\"fig-list\"><li>Zweig [flag set]: Com ruft sequenziell Rte_COMCbk_signalX() und Rte_COMCbk_signalY() auf; die RTE verarbeitet die Daten jeweils intern (internal processing()) und kehrt zurück.\n</li><li>Zweig [flag not set]: Es erfolgen keine weiteren Signal-Callbacks an die RTE.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ spiegelt das Diagramm die Realisierung des Konfigurationsparameters ComIPduSignalProcessing wider:</p>\n<ul class=\"fig-list\"><li>IMMEDIATE: Minimale Signallatenz, da Signalextraktion und RTE-Benachrichtigung direkt in Com_RxIndication ablaufen. Da Com_RxIndication typischerweise im ISR- oder Bus-Treiber-Kontext aufgerufen wird, müssen Callback-Funktionen (Rte_COMCbk_&lt;signal&gt;) extrem schlank und nicht-blockierend ausgelegt sein, um die Interrupt-Latenzen nicht zu verletzen.\n</li><li>DEFERRED: Entkopplung von hardwarenahem Empfang und Signalverarbeitung. Der ISR-Kontext wird auf das Kopieren der PDU-Payload in den internen COM-Puffer beschränkt. Das Entpacken und Auslösen der RTE-Callbacks erfolgt deterministisch im Rahmen des zyklischen Com_MainFunctionRx()-Tasks.\n</li><li>Für Entwickler relevant: Signal-Callbacks (signalX, signalY) werden in beiden Modi in identischer Signatur und Reihenfolge ausgelöst; das Diagramm verdeutlicht jedoch die signifikanten Unterschiede bezüglich Task-Kontext, Pufferbedarf und Ausführungszeitpunkt.\n</li></ul>"}, {"id": "FIG-53fe43a967248764", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Empfangs-Indikations-Handlings (Rx Indication Handling und Signal Unpacking) im AUTOSAR Classic Platform Kommunikations-Stack (AUTOSAR_SWS_COM). Das Diagramm stellt das Zusammenwirken zwischen dem PDU Router (PduR), dem AUTOSAR COM-Modul (Com) und der Runtime Environment (Rte) dar und visualisiert die architektonische Gegenüberstellung der beiden Signal-Entpackungsstrategien „Immediate“ (synchron im Aufrufkontext) und „Deferred“ (asynchron/gepuffert im Taskkontext).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Komponenten und Lebenslinien:</p>\n<ul class=\"fig-list\"><li>«module» PduR: Untere Schnittstellenschicht im Kommunikationsstack, leitet empfangene I-PDUs an das COM-Modul weiter.\n</li><li>«module» Com: Zentrales Kommunikationsmodul (mit Prozess-/Task-Symbol), zuständig für Signalextraktion, Pufferung und Routing.\n</li><li>«module» Rte: AUTOSAR Runtime Environment zur Signalweiterleitung an Software-Komponenten (SWCs).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li>Com_RxIndication(PduIdType, PduInfoType*): Synchrone Empfangsschnittstelle von Com, parametrisiert mit PDU-Identifikator und Zeiger auf PDU-Nutzdaten/Längeninformation.\n</li><li>Rte_COMCbk_signalX() / Rte_COMCbk_signalY(): Konfigurierbare COM-Callback-Funktionen zur Benachrichtigung der RTE über aktualisierte Signale (signalX, signalY).\n</li><li>internal processing(): Interne Verarbeitungsschritte innerhalb der RTE.\n</li><li>set flag, copy data(): Interne Operation von Com zur Datenpufferung und Flag-Setzung für den asynchronen Verarbeitungsmodus.\n</li><li>check flag(): Periodische interne Prüfung des Puffer-Flags durch Com (typischerweise innerhalb Com_MainFunctionRx()).\n</li></ul>\n<p class=\"fig-p\">Interaktionsrahmen (Combined Fragments):</p>\n<ul class=\"fig-list\"><li>alt Unpacking mit Operanden [Unpack.Immediate] und [Unpack.Deferred].\n</li><li>alt check flag (geschachtelt in Deferred) mit Operanden [flag set] und [flag not set].\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf teilt sich über das Combined Fragment „alt Unpacking“ in zwei alternative Pfade auf:</p>\n<ol class=\"fig-list\"><li>Modus [Unpack.Immediate]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt das Signal-Unpacking unmittelbar im Ausführungskontext der Indikation aus.\n</li><li>Com benachrichtigt nacheinander die RTE über synchrone Callback-Aufrufe Rte_COMCbk_signalX() und Rte_COMCbk_signalY().\n</li><li>Jede Callback-Ausführung stößt in der RTE ein internal processing() an und kehrt zu Com zurück.\n</li><li>Nach Abschluss der Benachrichtigungen kehrt der Kontrollfluss von Com_RxIndication an PduR zurück.\n</li></ul>\n<ol class=\"fig-list\"><li>Modus [Unpack.Deferred]:\n</li></ol>\n<ul class=\"fig-list\"><li>PduR ruft Com_RxIndication(PduIdType, PduInfoType*) auf Com auf.\n</li><li>Com führt die interne Operation set flag, copy data() aus (Kopieren der empfangenen Daten in den I-PDU-Puffer, Setzen des Verarbeitungs-Flags) und kehrt sofort synchron zu PduR zurück.\n</li><li>Zu einem späteren Zeitpunkt führt Com im eigenen Kontext check flag() aus.\n</li><li>Fragment „alt check flag“:\n<ul class=\"fig-list\"><li>Zweig [flag set]: Com ruft sequenziell Rte_COMCbk_signalX() und Rte_COMCbk_signalY() auf; die RTE verarbeitet die Daten jeweils intern (internal processing()) und kehrt zurück.\n</li><li>Zweig [flag not set]: Es erfolgen keine weiteren Signal-Callbacks an die RTE.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ spiegelt das Diagramm die Realisierung des Konfigurationsparameters ComIPduSignalProcessing wider:</p>\n<ul class=\"fig-list\"><li>IMMEDIATE: Minimale Signallatenz, da Signalextraktion und RTE-Benachrichtigung direkt in Com_RxIndication ablaufen. Da Com_RxIndication typischerweise im ISR- oder Bus-Treiber-Kontext aufgerufen wird, müssen Callback-Funktionen (Rte_COMCbk_&lt;signal&gt;) extrem schlank und nicht-blockierend ausgelegt sein, um die Interrupt-Latenzen nicht zu verletzen.\n</li><li>DEFERRED: Entkopplung von hardwarenahem Empfang und Signalverarbeitung. Der ISR-Kontext wird auf das Kopieren der PDU-Payload in den internen COM-Puffer beschränkt. Das Entpacken und Auslösen der RTE-Callbacks erfolgt deterministisch im Rahmen des zyklischen Com_MainFunctionRx()-Tasks.\n</li><li>Für Entwickler relevant: Signal-Callbacks (signalX, signalY) werden in beiden Modi in identischer Signatur und Reihenfolge ausgelöst; das Diagramm verdeutlicht jedoch die signifikanten Unterschiede bezüglich Task-Kontext, Pufferbedarf und Ausführungszeitpunkt.\n</li></ul>"}], "trans": [{"from": "FIG-406e2f09c10f7e14", "to": "FIG-9670781b449504d6", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9670781b449504d6", "to": "FIG-53fe43a967248764", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
